63	    });
64	
65	    connect(ui->buttonBox, &QDialogButtonBox::accepted, this, [=](){
66	        // create datapoints from individual traces
67	        measurements.clear();
68	        auto points = Trace::assembleDatapoints(traceChooser->getTraces());
69	        for(auto p : points) {
70	            measurements.push_back(p);
71	        }
72	        measurementCompleted();
73	    });
74	
75	    if(AppWindow::showGUI()) {
76	        measurementDialog->show();
77	    }
78	}
