80	void Deembedding::updateSCPINames()
81	{
82	    // Need to remove all options from the subnode list first, otherwise
83	    // name changes wouldn't work due to temporarily name collisions
84	    for(auto &option : options) {
85	        remove(option);
86	    }
87	    unsigned int i=1;
88	    for(auto &option : options) {
89	        option->changeName(QString::number(i));
90	        add(option);
91	        i++;
92	    }
93	}
94	
95	Deembedding::Deembedding(TraceModel &tm)
96	    : SCPINode("DEEMBedding"),
97	      measuringOption(nullptr),
98	      tm(tm),
99	      measuring(false),
100	      measurementDialog(nullptr),
101	      measurementUI(nullptr),
102	      sweepPoints(0)
103	{
104	    add(new SCPICommand("NUMber", nullptr, [=](QStringList params) -> QString {
105	        Q_UNUSED(params);
106	        return QString::number(options.size());
107	    }));
108	    add(new SCPICommand("TYPE", nullptr, [=](QStringList params) -> QString {
109	        unsigned long long index;
110	        if(!SCPI::paramToULongLong(params, 0, index)) {
111	            return SCPI::getResultName(SCPI::Result::Error);
112	        }
113	        if(index < 1 || index > options.size()) {
114	            return SCPI::getResultName(SCPI::Result::Error);
115	        }
116	        return DeembeddingOption::TypeToString(options[index-1]->getType()).replace(" ", "_");
117	    }));
118	    add(new SCPICommand("NEW", [=](QStringList params) -> QString {
119	        if(params.size() < 1) {
120	            return SCPI::getResultName(SCPI::Result::Error);
121	        }
122	        auto type = DeembeddingOption::TypeFromString(params[0].replace("_", " "));
123	        if(type == DeembeddingOption::Type::Last) {
124	            return SCPI::getResultName(SCPI::Result::Error);
125	        }
126	        auto option = DeembeddingOption::create(type);
127	        addOption(option);
128	        return SCPI::getResultName(SCPI::Result::Empty);
129	    }, nullptr));
130	    add(new SCPICommand("DELete", [=](QStringList params) -> QString {
131	        unsigned long long index;
132	        if(!SCPI::paramToULongLong(params, 0, index)) {
133	            return SCPI::getResultName(SCPI::Result::Error);
134	        }
135	        if(index < 1 || index > options.size()) {
136	            return SCPI::getResultName(SCPI::Result::Error);
137	        }
138	        removeOption(index-1);
139	        return SCPI::getResultName(SCPI::Result::Empty);
140	    }, nullptr));
141	    add(new SCPICommand("SWAP", [=](QStringList params) -> QString {
142	        unsigned long long index1, index2;
143	        if(!SCPI::paramToULongLong(params, 0, index1)) {
144	            return SCPI::getResultName(SCPI::Result::Error);
145	        }
146	        if(!SCPI::paramToULongLong(params, 1, index2)) {
147	            return SCPI::getResultName(SCPI::Result::Error);
148	        }
149	        if(index1 < 1 || index1 > options.size() || index2 < 1 || index2 > options.size()) {
150	            return SCPI::getResultName(SCPI::Result::Error);
151	        }
152	        swapOptions(index1-1, index2-1);
153	        return SCPI::getResultName(SCPI::Result::Empty);
154	    }, nullptr));
155	    add(new SCPICommand("CLEAR", [=](QStringList params) -> QString {
156	        Q_UNUSED(params);
157	        clear();
158	        return SCPI::getResultName(SCPI::Result::Empty);
159	    }, nullptr));
160	}
161	
162	void Deembedding::Deembed(DeviceDriver::VNAMeasurement &d)
163	{
164	    for(auto it = options.begin();it != options.end();it++) {
165	        if (measuring && measuringOption == *it) {
166	            // this option needs a measurement
167	            if (d.pointNum == 0) {
168	                if(measurements.size() == 0) {
169	                    // this is the first point of the measurement
170	                    measurements.push_back(d);
171	                }
172	            } else if(measurements.size() > 0) {
173	                // in the middle of the measurement, add point
174	                measurements.push_back(d);
175	
176	                if(d.pointNum == sweepPoints - 1) {
177	                    // this is the last point, measurement complete
178	                    measuring = false;
179	                    emit finishedMeasurement();
180	                    measurementCompleted();
181	                }
182	            }
183	
184	            if(measurementUI) {
185	                measurementUI->progress->setValue(100 * measurements.size() / sweepPoints);
186	            }
187	        }
188	        (*it)->transformDatapoint(d);
189	    }
190	}
191	
192	void Deembedding::Deembed(std::map<QString, Trace *> traceSet)
193	{
194	    auto points = Trace::assembleDatapoints(traceSet);
195	    if(points.size()) {
196	        // succeeded in assembling datapoints
197	        for(auto &p : points) {
198	            Deembed(p);
199	        }
200	        Trace::fillFromDatapoints(traceSet, points, true);
201	        for(auto t : traceSet) {
202	            t.second->setDeembeddingActive(true);
203	        }
204	    }
205	}
206	
207	void Deembedding::removeOption(unsigned int index)
208	{
209	    if(index < options.size()) {
210	        delete options[index];
211	        options.erase(options.begin() + index);
212	    }
213	    updateSCPINames();
214	    if(options.size() == 0) {
215	        emit allOptionsCleared();
216	    }
217	}
218	
219	void Deembedding::addOption(DeembeddingOption *option)
220	{
221	    options.push_back(option);
222	    connect(option, &DeembeddingOption::deleted, [=](DeembeddingOption *o){
223	        // find deleted option and remove from list
224	        auto pos = find(options.begin(), options.end(), o);
225	        if(pos != options.end()) {
226	            options.erase(pos);
227	        }
228	    });
229	    connect(option, &DeembeddingOption::triggerMeasurement, [=]() {
230	        measuringOption = option;
231	        startMeasurementDialog(option);
232	    });
233	    updateSCPINames();
234	    emit optionAdded();
235	}
236	
237	void Deembedding::swapOptions(unsigned int index1, unsigned int index2)
238	{
239	    if(index1 > options.size() || index2 > options.size() || index1 == index2) {
240	        return;
241	    }
242	    std::swap(options[index1], options[index2]);
243	    updateSCPINames();
244	}
245	
246	void Deembedding::clear()
247	{
248	    while(options.size() > 0) {
249	        removeOption(0);
250	    }
251	}
252	
253	bool Deembedding::isMeasuring()
254	{
255	    return measuring;
256	}
257	
258	std::set<unsigned int> Deembedding::getAffectedPorts()
259	{
260	    set<unsigned int> ret;
261	    for(auto o : options) {
262	        auto affected = o->getAffectedPorts();
263	        ret.insert(affected.begin(), affected.end());
264	    }
265	    return ret;
266	}
267	
268	void Deembedding::setPointsInSweepForMeasurement(unsigned int points)
269	{
270	    sweepPoints = points;
271	}
272	
273	nlohmann::json Deembedding::toJSON()
274	{
275	    nlohmann::json list;
276	    for(auto m : options) {
277	        nlohmann::json jm;
278	        jm["operation"] = DeembeddingOption::TypeToString(m->getType()).toStdString();
279	        jm["settings"] = m->toJSON();
280	        list.push_back(jm);
281	    }
282	    return list;
283	}
284	
285	void Deembedding::fromJSON(nlohmann::json j)
286	{
287	    // clear all options
288	    while(options.size() > 0) {
289	        removeOption(0);
290	    }
291	    for(auto jm : j) {
292	        QString operation = QString::fromStdString(jm.value("operation", ""));
293	        if(operation.isEmpty()) {
294	            qWarning() << "Skipping empty de-embedding operation";
295	            continue;
296	        }
297	        // attempt to find the type of operation
298	        DeembeddingOption::Type type = DeembeddingOption::Type::Last;
299	        for(unsigned int i=0;i<(int) DeembeddingOption::Type::Last;i++) {
300	            if(DeembeddingOption::TypeToString((DeembeddingOption::Type) i) == operation) {
301	                // found the correct operation
302	                type = (DeembeddingOption::Type) i;
303	                break;
304	            }
305	        }
306	        if(type == DeembeddingOption::Type::Last) {
307	            // unable to find this operation
308	            qWarning() << "Unable to create de-embedding operation:" << operation;
309	            continue;
310	        }
311	        qDebug() << "Creating math operation of type:" << operation;
312	        auto op = DeembeddingOption::create(type);
313	        if(jm.contains("settings")) {
314	            op->fromJSON(jm["settings"]);
315	        }
316	        addOption(op);
317	    }
318	}
319

